async (page) => {
  const { exec } = require('child_process');
  exec('chmod +x workspace/collect_diagnostics.sh', (error, stdout, stderr) => {
    if (error) {
      console.log(`Error: ${error}`);
      return;
    }
    if (stderr) {
      console.log(`Stderr: ${stderr}`);
      return;
    }
    console.log('Script is now executable');
  });
}

async (page) => {
  const { spawn } = require('child_process');
  const script = spawn('bash', ['workspace/collect_diagnostics.sh']);

  let output = '';

  script.stdout.on('data', (data) => {
    output += data.toString();
  });

  script.stderr.on('data', (data) => {
    output += 'Error: ' + data.toString();
  });

  script.on('close', (code) => {
    console.log(`Script exited with code ${code}`);
    console.log(output);
  });
}

async (page) => {
  const { spawn } = require('child_process');
  const script = spawn('python3', ['workspace/run_diagnostics.py']);

  let output = '';

  script.stdout.on('data', (data) => {
    output += data.toString();
  });

  script.stderr.on('data', (data) => {
    output += 'Error: ' + data.toString();
  });

  script.on('close', (code) => {
    console.log(`Python script exited with code ${code}`);
    console.log(output);
  });
}

async (page) => {
  const { execSync } = require('child_process');

  try {
    // Collect CPU information
    const cpuInfo = execSync('cat /proc/cpuinfo | grep "model name" | head -1', { encoding: 'utf-8' });

    // Collect load average
    const loadAvg = execSync('cat /proc/loadavg', { encoding: 'utf-8' });

    // Collect memory information
    const memInfo = execSync('free -h', { encoding: 'utf-8' });

    // Collect disk space information
    const diskInfo = execSync('df -h /', { encoding: 'utf-8' });

    console.log('=== System Diagnostics Report ===');
    console.log('CPU Information:');
    console.log(cpuInfo);
    console.log('Load Average:');
    console.log(loadAvg);
    console.log('Memory Usage:');
    console.log(memInfo);
    console.log('Disk Space (/):');
    console.log(diskInfo);
    console.log('=== End of Report ===');
  } catch (error) {
    console.error('Error collecting diagnostics:', error.message);
  }
}

